// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IC {
    function SetMinSum(uint) external;
    function SetLogFile(address) external;
    function Initialized() external;
    function Put(uint) external payable;
    function Collect(uint) external payable;
    function MinSum() external view returns (uint);
}

contract InvMutTest is Test {
    C c;
    Attacker atk;
    Log lg;

    function setUp() public {
        c = new C();
        atk = new Attacker(IC(address(c)));
        lg = new Log();
    }

    function testFuzz_property(uint256 minVal, uint256 newVal, uint256 deposit) public {
        minVal = bound(minVal, 0, 1e18);
        newVal = bound(newVal, minVal + 1, 2e18);
        deposit = bound(deposit, minVal, 2e18);

        vm.prank(address(atk));
        c.SetLogFile(address(lg));
        vm.prank(address(atk));
        c.SetMinSum(minVal);
        vm.prank(address(atk));
        c.Initialized();

        vm.deal(address(atk), deposit);
        vm.prank(address(atk));
        c.Put{value: deposit}(0);
        vm.warp(block.timestamp + 1);

        // reentrant SetMinSum attempt during Collect's external call
        atk.attack(newVal, deposit);

        // GENERAL RULE: MinSum is immutable once set via a reentrant attempt;
        // the reference never lets Collect's reentrancy change it.
        assertTrue(c.MinSum() == minVal);
    }
}

contract Attacker {
    IC public c;
    uint256 public newVal;

    constructor(IC _c) { c = _c; }

    function attack(uint256 _newVal, uint256 _am) external {
        newVal = _newVal;
        c.Collect(_am);
    }

    receive() external payable {
        c.SetMinSum(newVal);
    }
}

contract Log {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INIT = 1;

    function setUp() public {
        c = new C();
        Log lg = new Log();
        c.SetLogFile(address(lg));
        c.SetMinSum(INIT);
        c.Initialized();
    }

    function testFuzz_property(uint256 newVal, uint256 am) public {
        vm.assume(newVal != INIT);
        am = bound(am, 1, 10 ether);
        vm.warp(block.timestamp + 1);

        ReentrantAttacker attacker = new ReentrantAttacker(c, newVal);
        vm.deal(address(attacker), am);
        vm.prank(address(attacker));
        c.Put{value: am}(0);

        uint256 minSumBefore = c.MinSum();
        attacker.attack(am);

        // Rule: a reentrant SetMinSum from within Collect must never change MinSum.
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract Log {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 v;

    constructor(C _c, uint256 _v) {
        c = _c;
        v = _v;
    }

    function attack(uint256 am) public {
        c.Collect(am);
    }

    receive() external payable {
        c.SetMinSum(v);
    }
}

