// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address logAddr, uint96 amount, uint64 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(logAddr.code.length > 0);
        vm.assume(logAddr != address(c));
        c.SetLogFile(logAddr);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);
        (bool s, bytes memory ret) = logAddr.staticcall(
            abi.encodeWithSignature("History(uint256)", uint256(0))
        );
        assertTrue(s && abi.decode(ret, (address, string, uint256, uint256)).2 == uint256(amount));
    }
}

contract LogProbe {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        History.push(Message(_adr, _data, _val, block.timestamp));
    }
}
